<?php
declare(strict_types=1);
require __DIR__.'/app/qhse.php';$token=trim((string)($_GET['token']??''));$record=null;if(preg_match('/^[a-f0-9]{32}$/',$token))$record=rows("SELECT c.*,o.name company_name,cu.name customer_name,GROUP_CONCAT(e.name ORDER BY e.name SEPARATOR ', ') equipment_names FROM qhse_certificates c JOIN owners o ON o.id=c.owner_id JOIN commercial_customers cu ON cu.id=c.customer_id LEFT JOIN qhse_certificate_equipment ce ON ce.certificate_id=c.id LEFT JOIN equipment e ON e.id=ce.equipment_id WHERE c.verification_token=? AND c.status IN ('ISSUED','REVOKED','SUPERSEDED') GROUP BY c.id",[$token])[0]??null;$status=$record?qhse_certificate_display_status($record):null;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate verification · Nonagon</title><link rel="stylesheet" href="assets/css/operations.css"><link rel="stylesheet" href="assets/css/qhse-certificates.css"><link rel="stylesheet" href="assets/css/certificate-print.css"></head><body class="verification-page"><main><?php if(!$record):?><span class="verify-symbol invalid">!</span><h1>Certificate not verified</h1><p>The verification code is invalid or the certificate has not been issued.</p><?php else:?><span class="verify-symbol <?= $status==='REVOKED'?'invalid':'valid' ?>">✓</span><span class="eyebrow">Nonagon certificate verification</span><h1><?= e($record['certificate_number']) ?></h1><p>This record was issued by <strong><?= e($record['company_name']) ?></strong>.</p><dl><div><dt>Status</dt><dd><?= qhse_status_badge($status) ?></dd></div><div><dt>Certificate type</dt><dd><?= e(qhse_certificate_type_label($record['certificate_type'])) ?></dd></div><div><dt>Customer</dt><dd><?= e($record['customer_name']) ?></dd></div><div><dt>Equipment</dt><dd><?= e($record['equipment_names']) ?></dd></div><div><dt>Issue date</dt><dd><?= e($record['issue_date']) ?></dd></div><div><dt>Expiry</dt><dd><?= e($record['expiry_date']?:'No expiry') ?></dd></div><div><dt>Result</dt><dd><?= e($record['result']) ?></dd></div></dl><small>Verification confirms the platform record and its current status. It does not independently certify technical suitability.</small><?php endif;?></main></body></html>
